import { ArchiveTransport } from './ArchiveTransport'
import { ArchiveAudit } from './ArchiveAudit'

export class ArchiveUploadCoordinator {
  private transport: ArchiveTransport = new ArchiveTransport()
  private audit: ArchiveAudit = new ArchiveAudit()
  private archivePath: string = ''

  async sendArchive(): Promise<void> {
    if (this.archivePath.trim().length === 0) {
      this.audit.reject('Archive upload requires a source path')
      return
    }
    await this.transport.upload(this.archivePath)
    this.audit.record(this.archivePath)
  }
}

